CREATE TABLE IF NOT EXISTS d20_users (id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(64) NOT NULL UNIQUE,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('superadmin','admin','gamemaster','player','spectator') NOT NULL DEFAULT 'player',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS d20_user_settings (user_id BIGINT NOT NULL,setting_key VARCHAR(100) NOT NULL,setting_value JSON NOT NULL,PRIMARY KEY(user_id,setting_key),FOREIGN KEY(user_id) REFERENCES d20_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS d20_sessions (id CHAR(64) PRIMARY KEY,user_id BIGINT NOT NULL,expires_at TIMESTAMP NOT NULL,revoked BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES d20_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS d20_campaign_members (campaign_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role ENUM('owner','gamemaster','player','spectator') NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(campaign_id,user_id),FOREIGN KEY(user_id) REFERENCES d20_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS d20_audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NULL,action VARCHAR(120) NOT NULL,target_type VARCHAR(80) NULL,target_id VARCHAR(120) NULL,details JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),FOREIGN KEY(user_id) REFERENCES d20_users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS d20_server_settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value JSON NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
